349: 
350: .site-footer a:hover {
351:   color: var(--color-pink);
352:   text-decoration: underline;
353: }
354: 
355: .site-footer a:focus-visible {
356:   outline: 3px solid var(--color-pink);
357:   outline-offset: 2px;
358:   box-shadow: none;
359: }
360: 
361: .site-footer .footer-divider {
362:   border-color: rgba(255, 248, 238, 0.2);
363: }
364: 
365: .site-footer .footer-copyright {
366:   color: var(--color-cream);
367:   opacity: 0.9;
368: }

