1: /**
2:  * Shared vanilla JavaScript for navigation toggle (no Bootstrap JS),
3:  * safe localStorage helpers, light/cozy theme toggle, and live basket badge sync.
4:  */
5: (function () {
6:   "use strict";
7: 
8:   var CART_STORAGE_KEY = "sweetOvenCart";
9:   var THEME_STORAGE_KEY = "sweetOvenTheme";
10:   var memoryTheme = "light";
11: 
12:   function safeGetStorage(key) {
13:     try {
14:       return window.localStorage ? window.localStorage.getItem(key) : null;
15:     } catch (error) {
16:       return null;
17:     }
18:   }
19: 
20:   function safeSetStorage(key, value) {
21:     try {
22:       if (window.localStorage) {
23:         window.localStorage.setItem(key, value);
24:         return true;
25:       }
26:       return false;
27:     } catch (error) {
28:       return false;
29:     }
30:   }
31: 
32:   function safeRemoveStorage(key) {
33:     try {
34:       if (window.localStorage) {
35:         window.localStorage.removeItem(key);
36:         return true;
37:       }
38:       return false;
39:     } catch (error) {
40:       return false;
41:     }
42:   }
43: 
44:   function getTheme() {
45:     var saved = safeGetStorage(THEME_STORAGE_KEY);
46:     if (saved === "cozy" || saved === "light") {
47:       memoryTheme = saved;
48:       return saved;
49:     }
50:     return document.documentElement.getAttribute("data-theme") === "cozy" ? "cozy" : memoryTheme;
51:   }
52: 
53:   function applyTheme(theme) {
54:     var normalized = theme === "cozy" ? "cozy" : "light";
55:     memoryTheme = normalized;
56: 
57:     if (normalized === "cozy") {
58:       document.documentElement.setAttribute("data-theme", "cozy");
59:     } else {
60:       document.documentElement.removeAttribute("data-theme");
61:     }
62: 
63:     safeSetStorage(THEME_STORAGE_KEY, normalized);
64: 
65:     var toggleBtn = document.getElementById("themeToggleBtn");
66:     if (toggleBtn) {
67:       var isCozy = normalized === "cozy";
68:       toggleBtn.setAttribute("aria-pressed", String(isCozy));
69:       toggleBtn.setAttribute(
70:         "aria-label",
