364:         saveIngredientFilter("All");
365:         renderIngredientFilters();
366:         renderIngredients();
367:       });
368:     }
369: 
370:     if (!form || !select || !customInput) {
371:       return;
372:     }
373: 
374:     form.addEventListener("submit", function (event) {
375:       event.preventDefault();
376:       var chosen = customInput.value.trim() || select.value.trim();
377: 
378:       if (!chosen) {
379:         errorEl.textContent = "Please choose a standard request or type a custom kitchen note.";
380:         errorEl.classList.remove("d-none");
381:         select.focus();
382:         return;
383:       }
384: 
385:       if (chosen.length < 4) {
386:         errorEl.textContent = "Kitchen notes should be at least 4 characters long.";
387:         errorEl.classList.remove("d-none");
388:         customInput.focus();
389:         return;
390:       }
391: 
392:       var exists = savedDietaryPrefs.some(function (entry) {
393:         return entry.toLowerCase() === chosen.toLowerCase();
394:       });
395: 
396:       if (exists) {
397:         errorEl.textContent = '"' + chosen + '" is already saved in your kitchen notes.';
398:         errorEl.classList.remove("d-none");
399:         return;
400:       }
401: 
402:       errorEl.classList.add("d-none");
403:       savedDietaryPrefs.push(chosen);
404:       var persisted = saveDietaryPrefs();
405:       renderDietaryPrefs();
406:       showDietaryBanner(
407:         persisted
408:           ? "Saved kitchen note for future visits: " + chosen
409:           : "Added kitchen note for this session (browser storage unavailable): " + chosen
410:       );
411: 
412:       select.value = "";
413:       customInput.value = "";
414:     });
415: 
416:     if (clearBtn) {
417:       clearBtn.addEventListener("click", function () {
418:         savedDietaryPrefs = [];
419:         saveDietaryPrefs();
420:         renderDietaryPrefs();
421:         if (errorEl) {
422:           errorEl.classList.add("d-none");
423:         }
424:         showDietaryBanner("Cleared all saved kitchen notes.");
425:       });
