$files = @('index.html','pages\about.html','pages\contact.html')
foreach ($f in $files) {
  $c = Get-Content $f -Raw
  $hasHeader = $c -match '<header\b'
  $hasNav = $c -match '<nav\b'
  $hasMain = $c -match '<main\b'
  $hasFooter = $c -match '<footer\b'
  $hasBsJs = $c -match 'bootstrap\.bundle|bootstrap\.min\.js|jquery'
  $hasLorem = $c -match 'lorem\s+ipsum'
  Write-Output "=== $f ==="
  Write-Output "Semantic: header=$hasHeader nav=$hasNav main=$hasMain footer=$hasFooter | NoBsJs=$(-not $hasBsJs) | NoLorem=$(-not $hasLorem)"
  $imgs = [regex]::Matches($c, '<img[^>]+>')
  foreach ($m in $imgs) {
    $tag = $m.Value
    $hasAlt = $tag -match 'alt="[^"]+"'
    $srcMatch = [regex]::Match($tag, 'src="([^"]+)"')
    $src = $srcMatch.Groups[1].Value
    $baseDir = Split-Path $f -Parent
    $resolved = if ($baseDir) { Join-Path $baseDir $src } else { $src }
    $exists = Test-Path $resolved
    Write-Output "  IMG src=$src exists=$exists hasAlt=$hasAlt"
  }
  $inputs = [regex]::Matches($c, '<(input|select|textarea)[^>]*id="([^"]+)"')
  foreach ($inp in $inputs) {
    $id = $inp.Groups[2].Value
    $hasLbl = $c -match "for=`"$id`""
    Write-Output "  FIELD id=$id hasLabel=$hasLbl"
  }
}
if (Get-Command node -ErrorAction SilentlyContinue) {
  node --check js/site-nav.js; node --check js/home.js; node --check js/about.js; node --check js/contact.js
  Write-Output "Node syntax check exit: $LASTEXITCODE"
} else {
  Write-Output "Node not installed; skipping node --check"
}

$jsImgs = Select-String -Path js\home.js -Pattern 'images/[^"]+\.svg' -AllMatches | ForEach-Object { $_.Matches.Value } | Sort-Object -Unique
foreach ($p in $jsImgs) { Write-Output "$p exists=$(Test-Path $p)" }
git -c safe.directory=C:/Users/Admin/SE-D_Group10_TheSweetOven status --short

$allHtml = @('index.html') + (Get-ChildItem pages\*.html | ForEach-Object { "pages\$($_.Name)" })
foreach ($f in $allHtml) {
  $c = Get-Content $f -Raw
  $links = [regex]::Matches($c, '(?:href|src)="([^"#?]+)"') | ForEach-Object { $_.Groups[1].Value } | Where-Object { $_ -notmatch '^(https?:|tel:|mailto:|#)' } | Sort-Object -Unique
  $missing = @()
  $dir = Split-Path $f -Parent
  foreach ($l in $links) {
    $resolved = if ($dir) { Join-Path $dir $l } else { $l }
    if (-not (Test-Path $resolved)) { $missing += $l }
  }
  $hasSiteNav = $c -match 'site-nav\.js'
  $hasBsJs = $c -match 'bootstrap\.bundle|bootstrap\.min\.js|jquery'
  Write-Output "$f | missing=[$($missing -join ', ')] | site-nav=$hasSiteNav | hasBsOrJq=$hasBsJs"
}

